nodes.logical_schema:
enum AdminActorRef {
    Account(AccountId),
    DeveloperCli,
}

enum AuditOutcome {
    Succeeded,
    Rejected,
    Failed,
}

enum BoardCellKind {
    Free,
    Value(String),
}

enum CoordinationPhase {
    Prepared,
    LocallyCommitted,
    AwaitingPeerAcknowledgement,
}

enum RateLimitScope {
    AccountLogin,
    AccessLinkRedemption,
    PlayerRecovery,
}

enum TargetRef {
    Game(GameId),
    Account(AccountId),
    Session(SessionId),
}

enum TerminalOutcome {
    Resolved {
        winner_player_id: PlayerId,
        awarded_by_account_id: AccountId,
    },
    Cancelled {
        reason: CancellationReason,
        initiated_by: ActorRef,
    },
}

struct BoardCell {
    position: CellPosition,
    kind: BoardCellKind,
    is_matched: bool,
}

struct CellPosition {
    row: u8,       // One-based, matching the existing design.
    column: u8,    // One-based.
}

struct StorageMetadata {
    schema_version: u32,
}

enum HistoryOutcome {
    Resolved,
    Cancelled,
}

enum PublicationState {
    Pending,
    Published,
}

struct AccountAssignmentGate {
    account_id: AccountId, // primary key; row presence means assignment is blocked
}

struct GlobalReservation {
    game_id: Option<GameId>,
}

struct HistoryPlayerSnapshot {
    player_id: PlayerId,
    alias: String,
    side_length: u8,
    cells: Vec<BoardCell>,
}

struct WinnerSnapshot {
    player_id: PlayerId,
    alias: String,
}

enum AccountRole {
    Host,
    Admin,
}

enum AccountStatus {
    PendingEnrollment,
    Verified,
    ResetRequired,
}

enum CallMode {
    Random,
    Manual,
}

enum AccessLinkPurpose {
    Enrollment,
    PasswordReset,
}

enum AccountSessionScope {
    EnrollmentOnly,
    PasswordResetOnly,
    Normal,
}

enum AccountGameAccess {
    LiveView,
    FinalViewOnly,
}

enum CancellationReason {
    OperatorCancelled,
    HostIdleTimeout,
}

enum CompletedLine {
    Row(u8),
    Column(u8),
    MainDiagonal,
    AntiDiagonal,
}

enum ParticipantAccess {
    Live,
    FinalViewOnly,
}

enum ParticipantBinding {
    Player {
        player_id: PlayerId,
    },
    Spectator {
        spectator_id: SpectatorId,
    },
}

enum ViewerRef {
    Account(AccountId),
    Player(PlayerId),
    Spectator(SpectatorId),
}

enum ViewKey {
    Host,
    Player(PlayerId),
    Spectator(SpectatorId),
}

enum WinningPattern {
    SingleLine,
}

struct PlayerRecoveryRecord {
    player_id: PlayerId,
    answer_verifier: EncodedVerifier,
    normalization_version: u32,
    updated_at: Timestamp,
}

struct ViewRevisionRecord {
    view: ViewKey,
    revision: Revision,
}
